Base64 field extractor. JSON file + dotted key → decoded bytes.

```python
#!/usr/bin/env python3
"""Extract a dotted-path field from JSON and base64-decode it to bytes."""

from __future__ import annotations

import argparse
import base64
import json
import sys
from pathlib import Path
from typing import Any


def _walk(node: Any, dotted_key: str) -> Any:
    for part in dotted_key.split("."):
        if part == "":
            raise KeyError(f"empty segment in key path: {dotted_key!r}")
        if isinstance(node, list):
            try:
                node = node[int(part)]
            except (ValueError, IndexError) as exc:
                raise KeyError(f"list index {part!r} failed at {dotted_key!r}") from exc
        elif isinstance(node, dict):
            if part not in node:
                raise KeyError(f"missing key {part!r} in path {dotted_key!r}")
            node = node[part]
        else:
            raise TypeError(
                f"cannot descend into {type(node).__name__} at {part!r} ({dotted_key!r})"
            )
    return node


def extract_b64_field(json_path: str | Path, dotted_key: str) -> bytes:
    path = Path(json_path)
    with path.open("r", encoding="utf-8") as fh:
        data = json.load(fh)
    value = _walk(data, dotted_key)
    if isinstance(value, bytes):
        return value
    if not isinstance(value, str):
        raise TypeError(
            f"{dotted_key!r} is {type(value).__name__}, expected base64 string"
        )
    try:
        return base64.b64decode(value, validate=True)
    except Exception as exc:
        raise ValueError(f"{dotted_key!r} is not valid base64") from exc


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("json_path", type=Path)
    parser.add_argument("dotted_key")
    parser.add_argument(
        "-o",
        "--output",
        type=Path,
        help="write bytes to file; default stdout (binary)",
    )
    args = parser.parse_args()
    blob = extract_b64_field(args.json_path, args.dotted_key)
    if args.output is not None:
        args.output.write_bytes(blob)
    else:
        sys.stdout.buffer.write(blob)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

