)

_RCON = (0x00, 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1B, 0x36)


def _xtime(a: int) -> int:
    return ((a << 1) ^ 0x1B) & 0xFF if a & 0x80 else (a << 1)


def _sub_word(w: int) -> int:
    return (
        (_SBOX[(w >> 24) & 0xFF] << 24)
        | (_SBOX[(w >> 16) & 0xFF] << 16)
        | (_SBOX[(w >> 8) & 0xFF] << 8)
        | _SBOX[w & 0xFF]
    )


def _rot_word(w: int) -> int:
    return ((w << 8) | (w >> 24)) & 0xFFFFFFFF


def _expand_key(key: bytes) -> list[bytes]:
    n_k, n_r, n_b = 8, 14, 4
    w = [int.from_bytes(key[i : i + 4], "big") for i in range(0, 32, 4)]
    for i in range(n_k, n_b * (n_r + 1)):
        temp = w[i - 1]
        if i % n_k == 0:
            temp = _sub_word(_rot_word(temp)) ^ (_RCON[i // n_k] << 24)
        elif i % n_k == 4:
            temp = _sub_word(temp)
        w.append(w[i - n_k] ^ temp)
    return [
        b"".join(w[4 * r + j].to_bytes(4, "big") for j in range(4))
        for r in range(n_r + 1)
    ]


def _add_round_key(state: bytearray, rk: bytes) -> None:
    for i in range(16):
        state[i] ^= rk[i]


def _sub_bytes(state: bytearray) -> None:
    for i in range(16):
        state[i] = _SBOX[state[i]]


def _shift_rows(state: bytearray) -> None:
    s = state
    s[1], s[5], s[9], s[13] = s[5], s[9], s[13], s[1]
    s[2], s[6], s[10], s[14] = s[10], s[14], s[2], s[6]
    s[3], s[7], s[11], s[15] = s[15], s[3], s[7], s[11]


def _mix_columns(state: bytearray) -> None:
    for c in range(4):
        i = 4 * c
        a0, a1, a2, a3 = state[i], state[i + 1], state[i + 2], state[i + 3]
        state[i] = _xtime(a0) ^ _xtime(a1) ^ a1 ^ a2 ^ a3
        state[i + 1] = a0 ^ _xtime(a1) ^ _xtime(a2) ^ a2 ^ a3
        state[i + 2] = a0 ^ a1 ^ _xtime(a2) ^ _xtime(a3) ^ a3
        state[i + 3] = _xtime(a0) ^ a0 ^ a1 ^ a2 ^ _xtime(a3)


def _aes_encrypt_block(block: bytes, round_keys: list[bytes]) -> bytes:
    state = bytearray(block)
    _add_round_key(state, round_keys[0])
    for rk in round_keys[1:-1]:
        _sub_bytes(state)
        _shift_rows(state)
        _mix_columns(state)
        _add_round_key(state, rk)
    _sub_bytes(state)
    _shift_rows(state)
    _add_round_key(state, round_keys[-1])
    return bytes(state)


def _inc32(block: bytes) -> bytes:
    ctr = (int.from_bytes(block[12:16], "big") + 1) & 0xFFFFFFFF
    return block[:12] + ctr.to_bytes(4, "big")


def _xor(a: bytes, b: bytes) -> bytes:
    return bytes(x ^ y for x, y in zip(a, b))


def _gf_mul(x: int, y: int) -> int:
    r = 0xE1000000000000000000000000000000
    z = 0
    v = x
    for i in range(128):
        if (y >> (127 - i)) & 1:
            z ^= v
        lsb = v & 1
        v >>= 1
        if lsb:
            v ^= r
    return z


def _ghash(h: bytes, aad: bytes, ciphertext: bytes) -> bytes:
    h_int = int.from_bytes(h, "big")
    y = 0

    def feed(data: bytes) -> None:
        nonlocal y
        for off in range(0, len(data), 16):
            chunk = data[off : off + 16]
            if len(chunk) < 16:
                chunk = chunk + b"\x00" * (16 - len(chunk))
            y = _gf_mul(y ^ int.from_bytes(chunk, "big"), h_int)

    feed(aad)
    feed(ciphertext)
    len_block = (len(aad) * 8).to_bytes(8, "big") + (len(ciphertext) * 8).to_bytes(8, "big")
    y = _gf_mul(y ^ int.from_bytes(len_block, "big"), h_int)
    return y.to_bytes(16, "big")


def _gctr(round_keys: list[bytes], icb: bytes, data: bytes) -> bytes:
    if not data:
        return b""
    out = bytearray()
    cb = icb
    for off in range(0, len(data), 16):
        chunk = data[off : off + 16]
        keystream = _aes_encrypt_block(cb, round_keys)
        out.extend(_xor(chunk, keystream[: len(chunk)]))
        cb = _inc32(cb)
    return bytes(out)


class AuthenticationError(ValueError):
    """GCM tag mismatch."""


def decrypt_aes256_gcm(key: bytes, blob: bytes, aad: bytes = b"") -> bytes:
    if len(key) != 32:
        raise ValueError("key must be 32 bytes")
    if len(blob) < 28:
        raise ValueError("blob must be nonce(12) + ciphertext + tag(16)")
    nonce, tag, ciphertext = blob[:12], blob[-16:], blob[12:-16]
    round_keys = _expand_key(key)
    h = _aes_encrypt_block(b"\x00" * 16, round_keys)
    j0 = nonce + b"\x00\x00\x00\x01"
    plaintext = _gctr(round_keys, _inc32(j0), ciphertext)
    expected = _gctr(round_keys, j0, _ghash(h, aad, ciphertext))
    if not hmac.compare_digest(expected, tag):
        raise AuthenticationError("GCM tag mismatch")
    return plaintext
