# tests/conftest.py
from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Protocol

import pytest


class KeyProvider(Protocol):
    def get_key(self, key_id: str) -> bytes: ...


class RecordStore(Protocol):
    def put(self, rec_id: str, blob: bytes) -> None: ...
    def get(self, rec_id: str) -> bytes: ...
    def delete(self, rec_id: str) -> None: ...
    def list_ids(self) -> list[str]: ...


class KeyNotFoundError(KeyError):
    pass


class RecordNotFoundError(KeyError):
    pass


@dataclass
class FakeKeyProvider:
    keys: dict[str, bytes] = field(default_factory=dict)

    def get_key(self, key_id: str) -> bytes:
        try:
            return self.keys[key_id]
        except KeyError as exc:
            raise KeyNotFoundError(key_id) from exc

    def add(self, key_id: str, key: bytes | None = None) -> bytes:
        if key is None:
            key = os.urandom(32)
        if len(key) != 32:
            raise ValueError("key must be 32 bytes")
        self.keys[key_id] = key
        return key


@dataclass
class InMemoryStore:
    rows: dict[str, bytes] = field(default_factory=dict)

    def put(self, rec_id: str, blob: bytes) -> None:
        self.rows[rec_id] = blob

    def get(self, rec_id: str) -> bytes:
        try:
            return self.rows[rec_id]
        except KeyError as exc:
            raise RecordNotFoundError(rec_id) from exc

    def delete(self, rec_id: str) -> None:
        self.rows.pop(rec_id, None)

    def list_ids(self) -> list[str]:
        return list(self.rows)


@pytest.fixture
def key_provider() -> FakeKeyProvider:
    kp = FakeKeyProvider()
    kp.add("default")
    return kp


@pytest.fixture
def store() -> InMemoryStore:
    return InMemoryStore()
