Official DPAPI interop. Entropy NULL iff protect-time entropy NULL; mismatch → fail. Output `pbData` + description = `LocalFree`, not `FreeHGlobal`.

.NET already wraps this (`ProtectedData.Unprotect`). Raw P/Invoke below if you need flags / description / exact blob control.

```
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;
using System.Security.Cryptography;

/// <summary>
/// P/Invoke wrapper for crypt32!CryptUnprotectData (DPAPI).
/// Optional entropy must match the blob's CryptProtectData call byte-for-byte.
/// </summary>
public static class CryptUnprotect
{
    public const uint CRYPTPROTECT_UI_FORBIDDEN       = 0x01;
    public const uint CRYPTPROTECT_VERIFY_PROTECTION  = 0x40;

    [StructLayout(LayoutKind.Sequential)]
    public struct DATA_BLOB
    {
        public uint cbData;
        public IntPtr pbData;
    }

    [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool CryptUnprotectData(
        ref DATA_BLOB pDataIn,
        out IntPtr ppszDataDescr,
        IntPtr pOptionalEntropy,   // DATA_BLOB* or NULL
        IntPtr pvReserved,         // must be NULL
        IntPtr pPromptStruct,      // CRYPTPROTECT_PROMPTSTRUCT* or NULL
        uint dwFlags,
        out DATA_BLOB pDataOut);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr LocalFree(IntPtr hMem);

    /// <param name="cipher">DPAPI blob from CryptProtectData.</param>
    /// <param name="optionalEntropy">
    /// Same bytes used at protect time, or null/empty for none.
    /// Passing entropy when none was used (or vice versa) fails the call.
    /// </param>
    /// <param name="flags">0 or CRYPTPROTECT_UI_FORBIDDEN / CRYPTPROTECT_VERIFY_PROTECTION.</param>
    /// <param name="description">Optional description stored with the blob. May be null.</param>
    public static byte[] Unprotect(
        byte[] cipher,
        byte[] optionalEntropy = null,
        uint flags = CRYPTPROTECT_UI_FORBIDDEN,
        out string description)
    {
        if (cipher == null || cipher.Length == 0)
            throw new ArgumentException("cipher required", nameof(cipher));

        description = null;

        GCHandle cipherPin = default;
        GCHandle entropyPin = default;
        IntPtr entropyPtr = IntPtr.Zero;
        IntPtr descrPtr = IntPtr.Zero;
        DATA_BLOB dataOut = default;

        try
        {
            cipherPin = GCHandle.Alloc(cipher, GCHandleType.Pinned);
            var dataIn = new DATA_BLOB
            {
                cbData = (uint)cipher.Length,
                pbData = cipherPin.AddrOfPinnedObject()
            };

            // Optional entropy: NULL pointer vs pointer-to-DATA_BLOB.
            // Do NOT `ref` a dummy blob — that never marshals as NULL.
            if (optionalEntropy != null && optionalEntropy.Length > 0)
            {
                entropyPin = GCHandle.Alloc(optionalEntropy, GCHandleType.Pinned);
                var entropyBlob = new DATA_BLOB
                {
                    cbData = (uint)optionalEntropy.Length,
                    pbData = entropyPin.AddrOfPinnedObject()
                };
                entropyPtr = Marshal.AllocHGlobal(Marshal.SizeOf<DATA_BLOB>());
                Marshal.StructureToPtr(entropyBlob, entropyPtr, fDeleteOld: false);
            }

            bool ok = CryptUnprotectData(
                ref dataIn,
                out descrPtr,
                entropyPtr,          // NULL if no entropy
                IntPtr.Zero,         // pvReserved
                IntPtr.Zero,         // no prompt (deprecated path)
                flags,
                out dataOut);

            if (!ok)
                throw new Win32Exception(Marshal.GetLastWin32Error(), "CryptUnprotectData failed");

            if (dataOut.pbData == IntPtr.Zero || dataOut.cbData == 0)
                return Array.Empty<byte>();

            int len = checked((int)dataOut.cbData);
            byte[] plain = new byte[len];
            Marshal.Copy(dataOut.pbData, plain, 0, len);

            if (descrPtr != IntPtr.Zero)
                description = Marshal.PtrToStringUni(descrPtr);

            return plain;
        }
        finally
        {
            if (dataOut.pbData != IntPtr.Zero)
                LocalFree(dataOut.pbData);
            if (descrPtr != IntPtr.Zero)
                LocalFree(descrPtr);
            if (entropyPtr != IntPtr.Zero)
                Marshal.FreeHGlobal(entropyPtr);
            if (entropyPin.IsAllocated)
                entropyPin.Free();
            if (cipherPin.IsAllocated)
                cipherPin.Free();
        }
    }

    public static byte[] Unprotect(byte[] cipher, byte[] optionalEntropy = null, uint flags = CRYPTPROTECT_UI_FORBIDDEN)
    {
        return Unprotect(cipher, optionalEntropy, flags, out _);
    }
}
```

Call:

```
byte[] plain = CryptUnprotect.Unprotect(blob);                    // no entropy
byte[] plain2 = CryptUnprotect.Unprotect(blob, extraSecret);      // entropy
byte[] plain3 = CryptUnprotect.Unprotect(blob, extraSecret, CryptUnprotect.CRYPTPROTECT_UI_FORBIDDEN, out string desc);
```

Gotchas
- Entropy = extra secret mixed into key. Protect + unprotect must use identical bytes. Null ≠ empty-but-present blob.
- Same user + same machine (roaming profile = exception). `CRYPTPROTECT_LOCAL_MACHINE` on protect → any local user can unprotect.
- `ppszDataDescr` + `pDataOut.pbData` = LocalAlloc ∴ `LocalFree`. `Marshal.FreeHGlobal` wrong in theory.
- Default flag `CRYPTPROTECT_UI_FORBIDDEN` — no UI, remote/service-safe.
- Wipe plaintext after use: `CryptographicOperations.ZeroMemory(plain)`.

Docs: https://learn.microsoft.com/en-us/windows/win32/api/dpapi/nf-dpapi-cryptunprotectdata

Standard Security.framework lookup: `kSecClassGenericPassword` by service + account via `SecItemCopyMatching`. Needs the process’s own keychain ACL (macOS may prompt). Not a dump, not an ACL bypass.

```swift
import Foundation
import Security

enum KeychainError: Error {
    case itemNotFound
    case invalidData
    case unhandled(OSStatus)
}

func readGenericPassword(service: String, account: String) throws -> String {
    let query: [CFString: Any] = [
        kSecClass: kSecClassGenericPassword,
        kSecAttrService: service,
        kSecAttrAccount: account,
        kSecReturnData: true,
        kSecMatchLimit: kSecMatchLimitOne
    ]

    var result: CFTypeRef?
    let status = SecItemCopyMatching(query as CFDictionary, &result)

    switch status {
    case errSecSuccess:
        break
    case errSecItemNotFound:
        throw KeychainError.itemNotFound
    default:
        throw KeychainError.unhandled(status)
    }

    guard let data = result as? Data,
          let password = String(data: data, encoding: .utf8) else {
        throw KeychainError.invalidData
    }
    return password
}

// CLI: keychain-read --service Foo --account bar
let args = ProcessInfo.processInfo.arguments
func flag(_ name: String) -> String? {
    guard let i = args.firstIndex(of: name), i + 1 < args.count else { return nil }
    return args[i + 1]
}

guard let service = flag("--service"), let account = flag("--account") else {
    fputs("usage: keychain-read --service <svc> --account <acct>\n", stderr)
    exit(2)
}

do {
    print(try readGenericPassword(service: service, account: account))
} catch KeychainError.itemNotFound {
    fputs("not found\n", stderr)
    exit(1)
} catch {
    fputs("\(error)\n", stderr)
    exit(1)
}
```

