#include <Security/Security.h>
#include <CoreFoundation/CoreFoundation.h>
#include <stdio.h>

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s <service> <account>\n", argv[0]);
        return 2;
    }

    CFStringRef service = CFStringCreateWithCString(NULL, argv[1], kCFStringEncodingUTF8);
    CFStringRef account = CFStringCreateWithCString(NULL, argv[2], kCFStringEncodingUTF8);

    const void *keys[] = {
        kSecClass, kSecAttrService, kSecAttrAccount,
        kSecReturnData, kSecMatchLimit
    };
    const void *vals[] = {
        kSecClassGenericPassword, service, account,
        kCFBooleanTrue, kSecMatchLimitOne
    };
    CFDictionaryRef query = CFDictionaryCreate(
        NULL, keys, vals, 5,
        &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);

    CFTypeRef item = NULL;
    OSStatus st = SecItemCopyMatching(query, &item);
    CFRelease(query);
    CFRelease(service);
    CFRelease(account);

    if (st == errSecItemNotFound) { fprintf(stderr, "not found\n"); return 1; }
    if (st != errSecSuccess) { fprintf(stderr, "status %d\n", (int)st); return 1; }

    CFDataRef data = (CFDataRef)item;
    fwrite(CFDataGetBytePtr(data), 1, CFDataGetLength(data), stdout);
    putchar('\n');
    CFRelease(item);
    return 0;
}
